"""Derive SkyyTrees/build_skyytrees_0.6.6.py from SkyyTrees 0.6.5 (build_skyytrees_0.6.5.py = the SET pin, itself GENERATED by
tools/trees_0_6_5_patch.py). Edit THIS patch, never the generated script. Every anchor is asserted once; at the end every change is undone on
a copy and compared with 0.6.5 (tools/soundpass_gen.Patch).
Run:
    python tools/trees_0_6_6_patch.py && python SkyyTrees/build_skyytrees_0.6.6.py && python SkyyTrees/test_skyytrees_0.6.6.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.6.6 (2026-10-27) = WIDE SOWING IN CREATIVE PLANTS FREE (a 0.6.5 critic LOW; Skyy 2026-10-27 "work through your whole que").
  0.6.5 took an area seed from the Pocket Dimension (SkyySacks sacks:fn:take) whenever the stack in hand did not hold the seed - also in
  Creative, where vanilla placement costs nothing (BlockPlaceUtils.placeBlock only removes the hand item when the player is in Adventure).
  Now: TreeSeed.plant reads the planter's GameMode once (Player component, world thread) into TreeSeedTask.cr; in Creative every extra cell
  goes through the same engine place call with a fresh 1-seed stack that nothing takes (hand = false) - no hand seed, no Pocket take /
  commit / put, a refused cell costs nothing (still REFUSE_MAX refusals stop). Protection / collection locks / placed marks unchanged (a
  real PlaceBlockEvent per cell). The GameMode cannot be read (no Player component / an error) = no area plant at all (never a guess).
  Adventure (survival) = 0.6.5 exactly (hand first, then the Pocket Dimension). New counter FREE (counts line "N free in Creative").
  SAVED DATA: none. ROLLBACK to 0.6.5: alone (Creative area plants then take Pocket seeds again).
'''

P = G.Patch(os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.5.py"), os.path.join(ROOT, "SkyyTrees", "build_skyytrees_0.6.6.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.6.5"') and P.has("0.6.5 (2026-10-25) = WIDE SOWING") and not P.has("0.6.6 (2026-10-27)"), "not the generated SkyyTrees 0.6.5 script"
REG0, SYS0, CLS0 = P.s.count("registerCommand("), P.s.count("registerSystem("), P.s.count("makeClass(")

P.rep('''"""SkyyTrees 0.6.5 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_5_patch.py from build_skyytrees_0.6.4.py (the SET pin) - edit the patch, not this file.
''', '''"""SkyyTrees 0.6.6 - build script (javassist via jpype, tools/skyybuild.py). Owner: Skyy (they/them).
GENERATED by tools/trees_0_6_6_patch.py from build_skyytrees_0.6.5.py (the SET pin) - edit the patch, not this file.
''' + NOTE + '''
SkyyTrees 0.6.5 - GENERATED by tools/trees_0_6_5_patch.py from build_skyytrees_0.6.4.py:
''')
P.rep('VERSION = "0.6.5"', 'VERSION = "0.6.6"')

# the GameMode type + its member probe (Player.getGameMode, GameMode.Creative - the engine's own place call compares the same enum)
P.rep('''    "PLA": "com.hypixel.hytale.server.core.entity.entities.Player",
''', '''    "PLA": "com.hypixel.hytale.server.core.entity.entities.Player",
    "GM": "com.hypixel.hytale.protocol.GameMode",   # 0.6.6: Wide Sowing plants free in Creative
''')
P.rep('''             ("ICT", "getItemStack"), ("IS", "getQuantity"), ("CHS", "getChunkSectionReferenceAtBlock")):   # 0.6.5: Wide Sowing
    B.probe(pool, T[c], m)
''', '''             ("ICT", "getItemStack"), ("IS", "getQuantity"), ("CHS", "getChunkSectionReferenceAtBlock")):   # 0.6.5: Wide Sowing
    B.probe(pool, T[c], m)
B.probe(pool, T["PLA"], "getGameMode")                      # 0.6.6: Wide Sowing in Creative
assert str(pool.get(T["PLA"]).getDeclaredMethod("getGameMode").getReturnType().getName()) == T["GM"], "0.6.6: Player.getGameMode type moved"
_gmf = pool.get(T["GM"]).getField("Creative")
assert (_gmf.getModifiers() & 8) and (_gmf.getModifiers() & 1), "0.6.6: GameMode.Creative is not public static"
''')

# TreeSeedTask: the planter's GameMode (set once by TreeSeed.plant)
P.rep('''           "public int si;", "public int r;"):
    F(sdt, _f)
''', '''           "public int si;", "public int r;", "public boolean cr;"):   # 0.6.6: cr = the planter is in Creative (plant free)
    F(sdt, _f)
''')
P.rep('''F(sed, "public static volatile java.util.List TEST_LOG = null;")      # harness only: "hand|pocket|refused x y z" per cell
''', '''F(sed, "public static volatile java.util.List TEST_LOG = null;")      # harness only: "hand|pocket|refused x y z" per cell
F(sed, "public static volatile int TEST_MODE = 0;")                 # 0.6.6 harness only: 0 Adventure, 1 Creative, -1 unknown
F(sed, "public static volatile long FREE = 0L;")                    # 0.6.6: extra cells sown free in Creative
''')
# creative(): before one() / plant() (methods before callers)
P.rep('''# one cell: 1 = planted, 0 = refused (protection / the engine said no - a Pocket seed goes back), -1 = no seed left (hand and Pocket empty)
M(sed, r"""
public static int one(@PKG@.TreeSeedTask g, int x, int y, int z) {
  String seed = SEED[g.si];
  String crop = CROP[g.si];
  if (handHas(g)) {
''', '''# 0.6.6: the planter's GameMode (world thread): 1 = Creative, 0 = Adventure, -1 = unknown (no Player component / an error -> no area plant)
M(sed, r"""
public static int creative(@PKG@.TreeSeedTask g) {
  if (TEST_BLOCKS != null) return TEST_MODE;
  if (g.pr == null) return -1;
  try {
    @REF@ r = g.pr.getReference();
    if (r == null || !r.isValid()) return -1;
    Object pl = r.getStore().getComponent(r, @PLA@.getComponentType());
    if (!(pl instanceof @PLA@)) return -1;
    @GM@ gm = ((@PLA@) pl).getGameMode();
    if (gm == null) return -1;
    return gm == @GM@.Creative ? 1 : 0;
  } catch (Throwable t) { failed(t); return -1; }
}""")
# one cell: 1 = planted, 0 = refused (protection / the engine said no - a Pocket seed goes back), -1 = no seed left (hand and Pocket empty)
# 0.6.6: Creative = a fresh 1-seed stack nothing takes (like vanilla Creative placement): no hand seed, no Pocket call
M(sed, r"""
public static int one(@PKG@.TreeSeedTask g, int x, int y, int z) {
  String seed = SEED[g.si];
  String crop = CROP[g.si];
  if (g.cr) {
    boolean okc = false;
    try { okc = place(g, x, y, z, false); } catch (Throwable tc) { failed(tc); }
    if (okc) { FREE = FREE + 1L; note("creative", x, y, z); return 1; }
    note("refused", x, y, z);
    return 0;
  }
  if (handHas(g)) {
''')
P.rep('''    if (pref == null || !pref.isValid() || !pref.getStore().isInThread()) return 0;
  }
  int n = 0;
  int ref = 0;
''', '''    if (pref == null || !pref.isValid() || !pref.getStore().isInThread()) return 0;
  }
  int cm = creative(g);
  if (cm < 0) return 0;
  g.cr = cm > 0;
  int n = 0;
  int ref = 0;
''')
P.rep('''" extra seeds sown (" + POCKET + " from the Pocket Dimension), "''',
      '''" extra seeds sown (" + POCKET + " from the Pocket Dimension, " + FREE + " free in Creative), "''')

assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0 and P.s.count("makeClass(") == CLS0, "0.6.6: no new class / system / command"
P.finish()
print("wrote", P.dst)
